  recoveryCode_body: 'ଆପଣ ଆକାଉଣ୍ଟ ବିନା ବ୍ୟବହାର କରୁଛନ୍ତି। ଯଦି ଆପଣ ଏହି ବ୍ରାଉଜର୍ ସଫା କରନ୍ତି କିମ୍ବା ଡିଭାଇସ୍ ବଦଳାନ୍ତି, ଏହି 12ଟି ଶବ୍ଦ ଆପଣଙ୍କ ଡାଟା ଫେରାଇ ଆଣେ। ସେଗୁଡ଼ିକୁ କ୍ରମରେ ଲେଖି ରଖନ୍ତୁ। 30 ଦିନ ବ୍ୟବହାର ନ ହେଲେ, ଆପଣଙ୍କ ଡାଟା ଡିଲିଟ୍ ହୋଇଯାଏ ଏବଂ ଶବ୍ଦଗୁଡ଼ିକ କାମ କରିବା ବନ୍ଦ କରିଦିଏ।',
