  groupExit_leaveBlockedBody: '“{group}” ଗ୍ରୁପ୍‌ରେ ଆପଣଙ୍କର ଏବେ ବି ଖୋଲା ବ୍ୟାଲାନ୍ସ ଅଛି। ଏବେ ଛାଡିଲେ ଅନ୍ୟମାନଙ୍କ ପାଇଁ ଏହା ଅମେଣ୍ଟା ରହିଯିବ।',
  groupExit_leaveTitle: '“{group}” ଗ୍ରୁପ୍ ଛାଡିବେ?',
  groupExit_leaveBodyOne: 'ଆପଣଙ୍କ ହିସାବ ମେଣ୍ଟିଗଲା। ଗ୍ରୁପ୍ ଏହି ବ୍ରାଉଜର୍‌ରୁ ହଟିଯିବ ଏବଂ ଅନ୍ୟ ସଦସ୍ୟଙ୍କ ପାଇଁ ଆପଣଙ୍କ ଖର୍ଚ୍ଚରେ ଆପଣଙ୍କ ନାମ ରହିବ। ଫେରିବା ପାଇଁ, କେହି ଜଣେ ଆପଣଙ୍କୁ ପୁଣି ନିମନ୍ତ୍ରଣ କରିବାକୁ ପଡ଼ିବ।',
  groupExit_leaveBodyOther: 'ଆପଣଙ୍କ ହିସାବ ମେଣ୍ଟିଗଲା। ଗ୍ରୁପ୍ ଏହି ବ୍ରାଉଜର୍‌ରୁ ହଟିଯିବ ଏବଂ ଅନ୍ୟ {count} ଜଣ ସଦସ୍ୟଙ୍କ ପାଇଁ ଆପଣଙ୍କ ଖର୍ଚ୍ଚରେ ଆପଣଙ୍କ ନାମ ରହିବ। ଫେରିବା ପାଇଁ, କେହି ଜଣେ ଆପଣଙ୍କୁ ପୁଣି ନିମନ୍ତ୍ରଣ କରିବାକୁ ପଡ଼ିବ।',
  groupExit_leaveBodyAlone: 'ଆପଣଙ୍କ ହିସାବ ମେଣ୍ଟିଗଲା। ଗ୍ରୁପ୍‌ରେ ଅନ୍ୟ କେହି ଯୋଗ ଦେଇନାହାନ୍ତି, ତେଣୁ ଏହା ସବୁଦିନ ପାଇଁ ଡିଲିଟ୍ ହୋଇଯିବ।',
  groupExit_leaveConfirm: 'ଛାଡନ୍ତୁ',
  groupExit_deleteBlockedTitle: 'ଏବେ ବି ଖୋଲା ବ୍ୟାଲାନ୍ସ ଅଛି',
  groupExit_deleteBlockedBodyShort: 'ସମସ୍ତଙ୍କ ହିସାବ ମେଣ୍ଟିଗଲା ପରେ ହିଁ “{group}” ଗ୍ରୁପ୍ ଡିଲିଟ୍ କରାଯାଇପାରିବ।',
  groupExit_deleteBlockedBodyOne: 'ସମସ୍ତଙ୍କ ହିସାବ ମେଣ୍ଟିଗଲା ପରେ ହିଁ “{group}” ଗ୍ରୁପ୍ ଡିଲିଟ୍ କରାଯାଇପାରିବ। {count}ଟି ପେମେଣ୍ଟ ବାକି ଅଛି:',
  groupExit_deleteBlockedBodyOther: 'ସମସ୍ତଙ୍କ ହିସାବ ମେଣ୍ଟିଗଲା ପରେ ହିଁ “{group}” ଗ୍ରୁପ୍ ଡିଲିଟ୍ କରାଯାଇପାରିବ। {count}ଟି ପେମେଣ୍ଟ ବାକି ଅଛି:',
  groupExit_deleteTitle: '“{group}” ଗ୍ରୁପ୍ ଡିଲିଟ୍ କରିବେ?',
  groupExit_deleteBody: 'ସମସ୍ତଙ୍କ ହିସାବ ମେଣ୍ଟିଗଲା। ଗ୍ରୁପ୍, {bills} ଏବଂ ଇତିହାସ ସମସ୍ତଙ୍କ ପାଇଁ ଚାଲିଯିବ ({members})। ଏହାକୁ ପୂର୍ବାବସ୍ଥାକୁ ଫେରାଇହେବ ନାହିଁ।',
  groupExit_deleteBodyNoBills: 'ଗ୍ରୁପ୍ ସମସ୍ତଙ୍କ ପାଇଁ ଚାଲିଯିବ ({members})। ଏହାକୁ ପୂର୍ବାବସ୍ଥାକୁ ଫେରାଇହେବ ନାହିଁ।',
