  profile_signOutPendingTitleOther: '{count}ଟି ପରିବର୍ତ୍ତନ ଏପର୍ଯ୍ୟନ୍ତ ଅପଲୋଡ୍ ହୋଇନାହିଁ',
  profile_signOutPendingBody: 'ସିଙ୍କ୍ ଶେଷ ହେବା ପର୍ଯ୍ୟନ୍ତ ଆପଣଙ୍କ ଡାଟା ଏହି ବ୍ରାଉଜର୍‌ରେ ରହିବ। ସବୁକିଛି ଅପଲୋଡ୍ ହେବା ପରେ, ଆମେ ସାଇନ୍ ଆଉଟ୍ କରି ସ୍ଥାନୀୟ କପି ଲିଭାଇଦେବୁ।',
  profile_signOutPendingBodyOffline: 'ଆପଣ ଅଫଲାଇନ୍ ଅଛନ୍ତି। ସିଙ୍କ୍ ଶେଷ ହେବା ପର୍ଯ୍ୟନ୍ତ ଆପଣଙ୍କ ଡାଟା ଏହି ବ୍ରାଉଜର୍‌ରେ ରହିବ। ସବୁକିଛି ଅପଲୋଡ୍ ହେବା ପରେ, ଆମେ ସାଇନ୍ ଆଉଟ୍ କରି ସ୍ଥାନୀୟ କପି ଲିଭାଇଦେବୁ।',
