  profile_eraseTitle: 'ଏହି ବ୍ରାଉଜର୍‌ରୁ ପ୍ରୋଫାଇଲ୍ ଲିଭାଇବେ?',
  profile_eraseBody: 'ଆପଣଙ୍କ ଆକାଉଣ୍ଟରେ Google କିମ୍ବା Apple ସାଇନ୍ ଇନ୍ ନାହିଁ। ଆପଣ ସାଇନ୍ ଆଉଟ୍ କଲେ, ଆମେ ଏହି ବ୍ରାଉଜର୍‌ର କପି ଲିଭାଇଦେବୁ। ଫେରିବା ପାଇଁ, ଆପଣଙ୍କୁ ରିକଭରି କୋଡ୍ ଦରକାର। 30 ଦିନ ବ୍ୟବହାର ନ ହେଲେ, ଆକାଉଣ୍ଟ ଡିଲିଟ୍ ହୋଇଯାଏ ଏବଂ କୋଡ୍ କାମ କରିବା ବନ୍ଦ କରିଦିଏ।',
  profile_eraseBodyNoCode: 'ଆପଣ ଆକାଉଣ୍ଟ ବିନା ବ୍ୟବହାର କରୁଛନ୍ତି ଏବଂ ଏପର୍ଯ୍ୟନ୍ତ ସିଙ୍କ୍ କରିନାହାନ୍ତି, ତେଣୁ କୌଣସି ରିକଭରି କୋଡ୍ ନାହିଁ। ଆପଣ ଛାଡିଲେ, ଆପଣଙ୍କ ପ୍ରୋଫାଇଲ୍ ସବୁଦିନ ପାଇଁ ଚାଲିଯିବ।',
