  simplifyInfo_anyoneText: 'ଗ୍ରୁପ୍ ଏଡିଟ୍‌ରେ। କାର୍ଯ୍ୟକଳାପ ଦେଖାଏ କିଏ ବଦଳାଇଲେ, ଏବଂ ଯିଏ ଏବେ ଅନ୍ୟ କାହାକୁ ଦେବେ କିମ୍ବା ଅନ୍ୟ କାହାଠାରୁ ପାଇବେ, ସେ ନୋଟିଫିକେସନ୍ ପାଇବେ।',
